export const TYPES = [...new Set(BESTIARY_INDEX.map((e) => e.type))].sort();

export const indexEntry = (name) => BESTIARY_INDEX.find(
  (e) => e.name.toLowerCase() === String(name || '').toLowerCase()) || null;

// Where to look it up, as one line.
export const citation = (e) => (e && e.sources || [])
  .map((s) => s.page ? `${s.book} p. ${s.page}` : s.book).join('; ');

// Substring search over the name, with an optional type filter. Capped
// because the caller renders every hit and there are hundreds of them.
export function searchBestiary(query, { type = null, limit = 40 } = {}) {
  const q = String(query || '').trim().toLowerCase();
  if (!q && !type) return [];
  return BESTIARY_INDEX
    .filter((e) => (!type || e.type === type)
      && (!q || e.name.toLowerCase().includes(q)
        || e.affiliation.toLowerCase().includes(q)))
    .slice(0, limit);
}

// A placeholder for the board. No numbers, because the index has none:
// it arrives named and cited, and the GM fills in what the book says.
//
// Absent figures are 0, the same convention bestiary.js uses — the
// printed dash means the creature has none of that, and one spelling of
// "nothing on file" is better than two. isUnweighed() keeps it out of the
// difficulty reckoning either way.
export function indexToNpc(name) {
  const e = indexEntry(name);
  if (!e) return null;
  return {
    name: e.name, max: 1, ws: 0, bs: 0,
    toughnessBonus: 0, armour: 0, weapon: null,
    custom: true, note: citation(e)
  };
}
